// Get all fields from the webhook
const fields = $input.item.json.body.data.fields || [];

function getReadableValue(field) {
  if (field.type === 'MULTIPLE_CHOICE' && field.options && field.value) {
    const selectedId = field.value[0];
    const matchingOption = field.options.find(opt => opt.id === selectedId);
    return matchingOption ? matchingOption.text : field.value[0];
  }
  return field.value;
}

const mappedData = {
  name: '',
  email: '',
  company: '',
  tier: '',
  allFieldsText: '',
  challenge: 'Not provided'
};

fields.forEach(field => {
  const label = field.label ? field.label.toLowerCase() : '';

  if (label.includes('name') && !label.includes('company')) {
    mappedData.name = field.value;
  }
  if (field.type === 'INPUT_EMAIL') {
    mappedData.email = field.value;
  }
  if (label.includes('company')) {
    mappedData.company = field.value;
  }
  if (field.label === 'tier') {
    mappedData.tier = field.value;
  }
  if (field.type === 'TEXTAREA' && field.value) {
    mappedData.challenge = field.value;
  }
});

const allFieldsArray = [];
fields.forEach(field => {
  if (field.type !== 'HIDDEN_FIELDS' && field.value !== null) {
    const readableValue = getReadableValue(field);
    allFieldsArray.push(`${field.label}: ${readableValue}`);
  }
});

mappedData.allFieldsText = allFieldsArray.join('\n');

return {
  json: mappedData
};
